import classes from './Counter.module.css';
import {useSelector, useDispatch} from 'react-redux';

const Counter = () => {
  const dispatch = useDispatch();

  const counter = useSelector(state => state.counter);
  useSelector(state => state.sh)

  function handleInc(){
    dispatch({type:'increment'})
  }
  function handleDec(){
      dispatch({type:'decrement'})
  }
  function handleReset(){
    dispatch({type:'reset'})
  }

  function handleIncBy10(){
    dispatch({type:'incrementby10', payload:10})
  }

  const handleNone = () => {
    dispatch({type:'others'})
  };

  function handleToggle(){
    dispatch({type:'toggle'})
  }

  return (
    <main className={classes.counter}>
      <h1>Redux Counter</h1>
      <div className={classes.value}>{counter}</div>
      <div>
        <button onClick={handleDec}>-</button>
        <button onClick={handleReset}>Reset</button>
        <button onClick={handleInc}>+</button>
        <button onClick={handleIncBy10}>Increase by 10</button>
        <button onClick={handleNone}>None</button>
      </div>
      <button onClick={handleToggle} >Toggle Counter</button>
    </main>
  );
};

export default Counter;
